     9	using namespace std;
    10	
    11	int main()
    12	{
    13	//	cout << buf.numIO << " " << buf.numAllBlk << " " << buf.numFreeBlk << endl;
    14	
    15		// delete the old result files upon start every time
    16		char filename[40];
    17		for (int i = SELECT_RET_ADDR; i < HASH_S_ADDR + OFFSET; i++) {
    18			sprintf(filename, "%d.blk", i);
    19			remove(filename);
    20		}
    21		Buffer testBuf;
    22		if (!initBuffer(BUF_SIZE, BLK_SIZE, &testBuf)) {
    23			perror("Buffer Initialization Failed!\n");
    24			return -1;
    25		}
    26		pushToWrite(&testBuf, NULL, 0, 500000, true);
    27		freeBuffer(&testBuf);
    28	
    29		string cmd;
    30		cout << "Welcome!" << endl << endl;
    31		while (true) {
    32			// recreate the buffer every time
    33			Buffer buf; // A buffer
    34			if (!initBuffer(BUF_SIZE, BLK_SIZE, &buf)) {
    35				perror("Buffer Initialization Failed!\n");
    36				return -1;
    37			}
    38			cout << "> ";
    39			getline(cin, cmd);
    40			if (cmd == "exit") { // exit the program
    41				cout << "Bye!" << endl << endl;
    42				break;
    43			} else if (cmd == "select") { // select * from R where R.A = 40 or S.C = 60
    44				select(&buf);
    45			} else if (cmd == "project") { // select A from R
    46				project(&buf);
    47			} else if (cmd == "nlj") { // nested-loop-join
    48				nestedLoopJoin(&buf);
    49			} else if (cmd == "hj") { // hash-join
    50				hashJoin(&buf);
    51			} else if (cmd == "smj") { // sort-merge-join
    52				sortMergeJoin(&buf);
    53			}
    54			freeBuffer(&buf);
    55		}
    56	
    57		return 0;
    58	}
