Buffer *initBuffer(size_t bufSize, size_t blkSize, Buffer *buf)
{
	if (buf == NULL || blkSize == 0)
		return NULL;

	/* Every block occupies blkSize + 1 bytes in the buffer: one leading byte
	 * flags whether the slot is available, the remaining blkSize bytes are
	 * the block payload handed out to the caller. */
	buf->numIO = 0;
	buf->bufSize = bufSize;
	buf->blkSize = blkSize;
	buf->numAllBlk = bufSize / (blkSize + 1);
	buf->numFreeBlk = buf->numAllBlk;

	if ((buf->data = (unsigned char *)malloc(bufSize)) == NULL)
	{
		perror("Buffer Initialization Failed!\n");
		return NULL;
	}

	memset(buf->data, 0, bufSize); /* all slots start out BLOCK_AVAILABLE */

	return buf;
}

